   public static IResource createResourceByEl(String el) {
      ResourceExpression expression = ELHelper.getExpressionFromEL(el);
      if (expression != null) {
         Object result = expression.evaluate();
         if (result instanceof IResource) {
            return (IResource) result;
         }
      }
      return null;
