            String url = WxEndpoint.get("url.material.list");
            String body = "{\"type\":\"%s\",\"offset\":%s,\"count\":%s}";

            String response = wxClient.post(url, String.format(body, mediaType.name(), offset, count));
            logger.debug("list materials: {}", response);

