    // CHECKSTYLE:OFF eclipse generated
    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null) {
            return false;
        }
        if (getClass() != obj.getClass()) {
            return false;
        }
        Volume other = (Volume) obj;
        if (volume != other.volume) {
            return false;
        }
        return true;
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + (int) (volume ^ (volume >>> 32));
        return result;
    }

    // CHECKSTYLE:ON

    @Override
    public String toString() {
        return "" + asLot() + " LOT";
