        if (clazz == null) {
            clazz = LoggerHelper.class;
        }
        Logger logger = Logger.getLogger(clazz);
        if (throwable == null) {
            logger.warn(message);
        }
        if (throwable != null) {
            logger.warn(message, throwable);
        }
    }

    public static void error(String message) {
        error(null, message, null);
    }

